const input = require("fs").readFileSync(0, "utf8");
const [targetLine, numsLine] = input.trim().split("\n");
const target = Number(targetLine);
const nums = numsLine.trim().split(/\s+/).map(Number);
const path = [];
const results = [];

function search(start, sum) {
  if (sum === target) {
    results.push([...path]);
    return;
  }
  for (let i = start; i < nums.length; i++) {
    if (sum + nums[i] > target) {
      break;
    }
    path.push(nums[i]);
    search(i + 1, sum + nums[i]);
    path.pop();
  }
}

search(0, 0);
if (results.length === 0) {
  console.log("none");
}
for (const combo of results) {
  console.log(`{${combo.join(", ")}}`);
}
